@startuml

class House {
  + Address : string
  + BuildingMaterial : string
}

class Basement {
  + Name : string
  + Size : float
}

class EarthBasement extends Basement {
  + HumidityLevel : float
}

class ConcreteBasement extends Basement {
}

class SemiDetachedHouse extends House {
  + HasGarden : boolean
  + WindowCount : int
}

class Carport {
  + IsDouble : boolean
  + HasFlatRoof : boolean
}

class Garage {
  + HasAutomaticDoor : boolean
}

class Company {
  + Name : string
  + Address : string
}

class JobLog {
  + Hours : float
  + Price : float
}

House "0..1" *-- "0..1" Basement
House "1" -- "0..*" JobLog
Company "1" -- "0..*" JobLog
House "1" -- "0..*" JobLog : serviced by
SemiDetachedHouse "1" -- "2" Carport
SemiDetachedHouse "1" -- "0..1" Garage

@enduml

